#ifndef CEXOINPUTEVENTDESC_H
#define CEXOINPUTEVENTDESC_H

// One input-event binding: event id N is bound to control C on device D. The event class selects
// which of the three descriptor kinds is built, so this base is also the common prefix of them.
class CExoInputEventDesc {
public:
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 2 slots
    virtual int IsDetailed();
    virtual int Is2Button();
    // </VTABLE-GEN>

    int m_nState;
    int m_nClassCount;
    int m_nCooldown;
    int m_nId;
    int m_nEventClass;
    int m_nDevice;
    int m_nKeyCode;

    CExoInputEventDesc() {}

    CExoInputEventDesc(unsigned int nId, int nEventClass, int nDevice)
    {
        m_nState = 0;
        m_nClassCount = 0;
        m_nCooldown = 0;
        m_nId = static_cast<int>(nId);
        m_nEventClass = nEventClass;
        m_nDevice = nDevice;
    }
};

#endif // CEXOINPUTEVENTDESC_H

#ifndef CEXOINPUTEVENTDESCDETAILED_H
#define CEXOINPUTEVENTDESCDETAILED_H


// Axis event (class 3): the base binding plus a per-axis scale pair.
class CExoInputEventDescDetailed : public CExoInputEventDesc {
public:
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 2 slots
    virtual int IsDetailed();
    // </VTABLE-GEN>

    int   m_bScaled;
    int   m_nAxisState;
    float m_fScaleX;
    float m_fScaleY;

    CExoInputEventDescDetailed()
    {
        m_bScaled = 0;
        m_nAxisState = 0;
        m_fScaleX = 1.0f;
        m_fScaleY = 1.0f;
    }

    CExoInputEventDescDetailed(unsigned int nId, int nEventClass, int nDevice)
        : CExoInputEventDesc(nId, nEventClass, nDevice)
    {
        m_bScaled = 0;
        m_nAxisState = 0;
        m_fScaleX = 1.0f;
        m_fScaleY = 1.0f;
    }
};

#endif // CEXOINPUTEVENTDESCDETAILED_H

