// One entry in a keyboard or device buffer; the high bit of m_flags marks a captured key-down.
struct CExoInputKeyEvent {
    int           m_nKeyCode;
    union {
        int           m_nValue;   // the key's state: the axis value for a stick
        unsigned char m_flags;    // ... whose low byte's bit 7 is "down" for a key
    };
    int           m_nTimeStamp;
    int           m_nSequence;
#if KOTOR1
    int           m_nAppData;
#else
    long long     m_nAppData;
#endif
};

// A heap-backed device event buffer; the constructor allocates and the destructor frees.
struct CExoDeviceBuffer {
    CExoInputKeyEvent* m_pEntries;
    unsigned int       m_nCount;
    unsigned char      m_aReserved1[4];
    CExoDeviceBuffer();
    ~CExoDeviceBuffer();
};

// Raw mouse sample from the device's GetMouseState, in mickies.
struct CExoMouseState {
    int m_dx;
    int m_dy;
    int m_dz;
    int m_nButtons;
};

// One of the six event classes CExoInputInternal holds by value: a binding list per input device
// plus a bitmask of the event ids registered in it.
struct CExoInputClass {
    CExoInputClass();
    ~CExoInputClass();
    CExoString                     m_sName;
    CExoLinkedList<int*>           m_unboundList;
    CExoLinkedList<int*>           m_apDeviceLists[6];
    CExoArrayList<unsigned int>   m_aEventBits;
};

// A repeat-timer record in the repeat list, keyed by event index.
#pragma pack(push, 4)
struct CInputEventRepeat {
    int          m_nEventIndex;
    unsigned int m_nRepeatWait;
    unsigned int m_nRepeatRate;
    int          m_nRepeatState;
    int          m_nLatchedState;
    int          m_nEmittedValue;
    int          m_nRepeatCount;
};
#pragma pack(pop)

// Mouse sensitivity divisor (max mickies per frame).
extern float fMaxMickies;

